local BaseEffect = import('Game.Chapter.NewChapterEffect.BaseEffect')
local base = BaseEffect

---@class SceneBgPosEffect : BaseEffect
local SceneBgPosEffect = Class("SceneBgPosEffect", BaseEffect)
local ResourceModule = CS.Engine.Modules.ResourceModule
local cs_coroutine = require 'XLua.cs_coroutine'
local Yielders = CS.Engine.Lib.Yielders
local KTool = CS.Engine.Lib.KTool
local NewChapterConstants = import('Game.Chapter.NewChapterConstants')

function SceneBgPosEffect:__init()
    self._isFinish = nil
    self._loadedRes = nil
    self._co = nil
    self.parameters = nil
    self.pos = nil
    self.scale = nil
end

function SceneBgPosEffect:__delete()
    self._isFinish = nil
    self._loadedRes = nil
    self._co = nil
    self.parameters = nil
    self.pos = nil
    self.scale = nil
end

---@param parameters NewChapter2DVo
function SceneBgPosEffect:Initialize(parameters)
    base.StartEffect(self, parameters)
    self.parameters = parameters
    local posVo = CfUtils.GetCfVo(AutoIds.IdSetting6121,"ChapterBgEffectVo",self.parameters.bgEffectPos)
    local scale = 0.7
    if not isNull(posVo) then
        self.pos = Vector3.New(checkNumber(posVo.EffectPosition[1]),checkNumber(posVo.EffectPosition[2]),checkNumber(posVo.EffectPosition[3]))
        scale = posVo.EffectScale
    end
    self.scale = Vector3.New(scale,scale,scale)
end

function SceneBgPosEffect:StartEffect(object)
    base.StartEffect(self, object)
    self.isFinish = false
    if not isNull(self._loadedRes) then
        self.isFinish = true
        return
    end
    self.co = cs_coroutine.start(function()
        local config = NewChapterConstants.SceneBaseEffectConfig[self.parameters.screenAnim]
        if config then
            local loader = ResourceModule.LoadBundleAsync(config.Path, nil, true)
            while not loader.IsCompleted do
                coroutine.yield(Yielders.EndOfFrame)
            end

            if loader.IsSuccess then

                local modelIns = loader:Instantiate()
                KTool.ChangeAllLayer(modelIns, 17, 0)

                modelIns.transform:SetParent(object.transform)
                modelIns.transform.localPosition = not isNull(self.pos) and self.pos or config.Position
                modelIns.transform.localScale = self.scale
                modelIns.transform.localRotation = CS.UnityEngine.Quaternion.identity
                self._loadedRes = modelIns

                KTool.SetActive(modelIns.gameObject, true)


                self.loader = loader
            else
                loader:Release()
            end

            self.isFinish = true
            self.co = nil
        else
            printError("sceneAin  id  %s  在 NewChapterConstants.SceneBaseEffectConfig 中没有配置！！！！")
        end
    end)
end

function SceneBgPosEffect:IsFinish()
    base.IsFinish(self)
    return true
end

function SceneBgPosEffect:EndEffect(object)
    base.EndEffect(self, object)
end

function SceneBgPosEffect:RemoveEffect(object)
    base.RemoveEffect(self, object)
    KTool.SafeDelete(self._loadedRes)
    if not isNull(self.loader) then
        self.loader:Release()
    end
end

return SceneBgPosEffect
